<?php
require_once __DIR__ . '/assets/php/bootstrap.php';
$slug=trim((string)($_GET['slug']??''));$legacyId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$product=null;
if($legacyId && $slug===''){$s=db()->prepare('SELECT slug FROM producto WHERE id_producto=:id AND activo=TRUE');$s->execute(['id'=>$legacyId]);$legacySlug=$s->fetchColumn();if($legacySlug){redirect('producto.php?slug='.rawurlencode($legacySlug));}}
if($slug!=='' && preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)){$s=db()->prepare('SELECT p.*,c.nombre categoria,al.titulo album,al.id_album FROM producto p JOIN categoria_producto c ON c.id_categoria=p.categoria_id LEFT JOIN album al ON al.id_album=p.album_id WHERE p.slug=:slug AND p.activo=TRUE');$s->execute(['slug'=>$slug]);$product=$s->fetch();}if(!$product)http_response_code(404);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($product['nombre']??'Producto no disponible')?> — SIDE B</title><link rel="stylesheet" href="assets/css/variables.css"><link rel="stylesheet" href="assets/css/global.css"><link rel="stylesheet" href="assets/css/components.css"><link rel="stylesheet" href="assets/css/home.css"><link rel="stylesheet" href="assets/css/shop.css"></head><body><header class="site-header"><div class="container header-inner"><a class="brand" href="index.php">SIDE B<span class="brand-dot">.</span></a><nav class="primary-nav"><a class="nav-link" href="tienda.php">Tienda</a></nav><?=logout_control()?></div></header><main class="product-detail"><div class="container product-detail-grid"><?php if(!$product):?><p>El producto que buscas no está disponible.</p><?php else:?><div class="product-detail-art visual-surface visual-surface--record"><?php if($product['imagen']):?><img src="<?=e($product['imagen'])?>" alt="<?=e($product['nombre'])?>"><?php endif;?></div><div class="product-detail-copy"><p class="card-kicker"><?=e($product['categoria'])?></p><h1><?=e($product['nombre'])?></h1><p class="price">$<?=number_format((float)$product['precio'],2)?></p><div class="product-description"><p><?=nl2br(e((string)$product['descripcion']))?></p><p><?= $product['stock']>0?'Disponible: '.(int)$product['stock'].' unidades.':'Agotado.'?></p></div><?php if($product['stock']>0):?><a class="button button-primary" href="carrito.php">Añadir al carrito →</a><?php endif;?></div><?php endif;?></div></main><?=sideb_footer()?></body></html>
